INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115371, 'spa', 'Hermosura y conveniencia', 'Ser hermoso, agraciado o apropiado. Cantares 1:10 elogia: «Hermosas son tus mejillas entre los pendientes, tu cuello entre los collares.» Isaías 52:7 celebra: «¡Cuán hermosos son sobre los montes los pies del que trae buenas nuevas!», los mensajeros de paz son bellos. El Salmo 93:5 declara: «La santidad conviene a tu casa, oh SEÑOR, por los siglos», la santidad es adecuada y propia de la morada de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115372, 'spa', 'Pastos, praderas', 'Terreno abierto de pastoreo, pastos o praderas, a menudo barómetro de bendición o juicio divino. El SEÑOR conduce a su pueblo a «verdes pastos» (Sal 23:2), los pastos del desierto destilan abundancia (Sal 65:12) y los enemigos aspiran a apoderarse de «los pastos de Dios» (Sal 83:12). Pastos desolados señalan infidelidad al pacto (Jer 9:10; Jl 1:19-20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115380, 'spa', 'Hermosa, bella', 'Físicamente hermosa, bella o agraciada. Se aplica a la mujer amada en el Cantar de los Cantares (1:5 «morena pero hermosa»; 6:4 en paralelo con יָפָה ''bella'') y a sus rasgos (2:14 su semblante; 4:3 su boca). También se usa figuradamente de Jerusalén como mujer hermosa en Jeremías 6:2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115381, 'spa', 'Apropiado, decoroso', 'Apropiado, conveniente o decoroso en sentido moral o social. En los Salmos, la alabanza se declara «apropiada» para los rectos (Sal 33:1; 147:1). Proverbios lo aplica en sentido negativo: el habla refinada no conviene al necio (17:7), el lujo no es decoroso para el insensato (19:10) y la honra no es adecuada para el necio (26:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115387, 'spa', 'oráculo, declaración divina', 'Sustantivo profético solemne empleado casi exclusivamente en la frase constructa neʾum YHWH (''declara el SEÑOR'') para señalar que el discurso es un oráculo divino transmitido a través del profeta. Fuera de esta fórmula, introduce las declaraciones extáticas de Balaam (Nm 24:3, 15) y las últimas palabras de David (2 S 23:1). Su comportamiento sintáctico rígido — siempre en estado constructo, nunca flexionado de forma independiente — le otorga un carácter formulaico y litúrgico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115401, 'spa', 'Sustantivo agentivo femenino -- la adultera, derivado de participios femeninos s', 'Sustantivo agentivo femenino -- la adultera, derivado de participios femeninos sustantivados. Siete apariciones identifican a la mujer en el acto, de manera prominente en las devastadoras alegorias de Ezequiel: Jerusalen como la esposa adultera que ''toma extranos en lugar de su marido'' (Ez 16:32), juzgada ''como mujeres que cometen adulterio'' (Ez 23:45). Lv 20:10 empareja a la adultera con el adultero para igual pena capital.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115402, 'spa', 'Formas verbales finitas del Qal -- el acto basico de cometer adulterio', 'Formas verbales finitas del Qal -- el acto basico de cometer adulterio. Cinco apariciones, incluyendo la prohibicion del Decalogo misma (Ex 20:14; Dt 5:18), junto con la casuistica legal de Lv 20:10 (dos veces, para el hombre que ''comete adulterio con'' la esposa de otro). Jer 3:9 aporta la gran extension metaforica: Israel ''cometio adulterio con la piedra y el arbol'' -- la idolatria como traicion conyugal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115403, 'spa', 'Formas finitas del Piel intensivo -- cometer adulterio con fuerza habitual, enfa', 'Formas finitas del Piel intensivo -- cometer adulterio con fuerza habitual, enfatica o intensificada. Siete apariciones, concentradas en las acusaciones profeticas de Jeremias y Ezequiel. Jer 5:7 acusa al pueblo de acudir en tropel a la casa de la ramera; Jer 29:23 enjuicia a los falsos profetas que ''cometieron adulterio con las esposas de sus projimos.'' Ez 23:37 acusa tanto a Ohola como a Oholiba de adulterio -- aqui con idolos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115406, 'spa', 'Sustantivo agentivo masculino -- el adultero, derivado de participios Qal y Piel', 'Sustantivo agentivo masculino -- el adultero, derivado de participios Qal y Piel sustantivados. Nueve apariciones identifican al perpetrador masculino del adulterio, ya sea en la prescripcion legal (Lv 20:10, donde tanto el adultero como la adultera seran ejecutados), la literatura sapiencial (Pr 6:32, ''el que comete adulterio carece de entendimiento''), o la denuncia profetica (Is 57:3, ''hijos de hechicera, descendencia del adultero'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115408, 'spa', 'Formas de infinitivo absoluto -- el acto del adulterio como sustantivo verbal o ', 'Formas de infinitivo absoluto -- el acto del adulterio como sustantivo verbal o intensificador adverbial. Tres apariciones, todas en listas profeticas de violaciones del pacto. Jer 7:9 encadena infinitivos: ''robar, matar, cometer adulterio, jurar en falso...'' -- un catalogo de mandamientos quebrantados. Jer 23:14 incluye igualmente el adulterio en una lista de pecados de los profetas. Os 4:2 lanza la famosa requisitoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115424, 'spa', 'El Piel intensifica el desprecio básico hasta convertirlo en desdén activo y del', 'El Piel intensifica el desprecio básico hasta convertirlo en desdén activo y deliberado dirigido a personas, frecuentemente a Dios o a su pueblo. Se usa cuando Israel provoca al SEÑOR (Nm 14:11, 23) o cuando los impíos tratan con desprecio a los siervos de Dios (Dt 31:20; 1 S 2:17). El Piel transmite aquí un rechazo habitual y voluntario de la autoridad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115426, 'spa', 'El Qal básico expresa desprecio directo o rechazo, tratando como inútiles la sab', 'El Qal básico expresa desprecio directo o rechazo, tratando como inútiles la sabiduría, el consejo o la corrección. Proverbios concentra este uso: despreciar la reprensión (1:30), menospreciar la disciplina (5:12; 15:5). El paralelismo con rechazar ''consejo'' e ''instrucción'' muestra que este sentido apunta a la obstinación intelectual y moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115427, 'spa', 'Raíz homógrafa completamente distinta que significa ''florecer, brotar'', atestigu', 'Raíz homógrafa completamente distinta que significa ''florecer, brotar'', atestiguada únicamente en Eclesiastés 12:5, donde el almendro florece como figura del cabello blanco de la vejez. El abismo semántico respecto a ''despreciar'' es total; se trata de una coincidencia léxica de consonantes compartidas, no de una extensión metafórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115428, 'spa', 'Uso especializado del Piel donde el desprecio alcanza el nivel de blasfemia', 'Uso especializado del Piel donde el desprecio alcanza el nivel de blasfemia: palabra o acción que difama directamente el honor y la santidad de Dios. El caso paradigmático es 2 Samuel 12:14, donde el pecado de David ha ''menospreciado gravemente'' (infinitivo absoluto + verbo finito) al SEÑOR. En el Salmo 74:10, 18, el salmista se lamenta de cuánto tiempo el enemigo blasfemará el nombre de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115442, 'spa', 'El Hitpael (reflexivo-pasivo) aparece una sola vez en Isaías 52', 'El Hitpael (reflexivo-pasivo) aparece una sola vez en Isaías 52:5, donde el nombre de Dios ''es blasfemado continuamente'' entre las naciones a causa del exilio de Israel. Esta construcción pasiva hace que el foco recaiga sobre el sufrimiento de la reputación de Dios, no sobre los agentes humanos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115448, 'spa', 'Blasfemias contra Dios', 'El plural «blasfemias» capta actos múltiples o habituales de desprecio contra el SEÑOR. En Nehemías, estas provocaciones (נֶאָצוֹת גְדֹלוֹת, «grandes blasfemias») constituyen rebelión contra el pacto: fabricar ídolos y rechazar la ley de Dios. En Ezequiel 35:12, las נָאָצוֹת de Edom fueron pronunciadas contra los montes de Israel, pero Dios las escuchó como afrentas contra su pueblo y, por tanto, contra sí mismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115450, 'spa', 'Gemido de aflicción', 'Gemido, el sonido del sufrimiento profundo o la opresión. Éxodo 2:24 es clave: ''Dios oyó el gemido de ellos (נְאָקָתָם) y se acordó de su pacto con Abraham, Isaac y Jacob''; el gemido de Israel en la esclavitud egipcia movió a Dios a iniciar el éxodo. Éxodo 6:5 lo repite: ''He oído el gemido de los hijos de Israel.'' Jueces 2:18 explica el patrón divino de enviar libertadores al oír el gemido de su pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115452, 'spa', 'Nob (nombre propio)', 'La ciudad de Nob, asentamiento sacerdotal cercano a Jerusalén asociado con el trágico episodio de David y Ahimelec. La masacre de sus sacerdotes por Saúl (1 S 22:19) la convirtió en símbolo de extralimitación real contra el sacerdocio. Isaías 10:32 la sitúa como último punto antes de un asalto contra Jerusalén, confirmando su proximidad a la capital.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115455, 'spa', 'profetizar, proclamar oráculo', 'Profetizar en el Nifal (73 veces): la forma estándar para pronunciar oráculos divinos, mandatos de profetizar y descripciones participiales de ''el que profetiza''. Es la voz de la profecía clásica: a Jeremías se le ordena ''¡profetiza!'' (Jer 19:14; 20:6), Ezequiel habla sobre los huesos secos (Ez 37:7), y el Cronista registra la profecía levítica con instrumentos (1 Cr 25:2-3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115458, 'spa', 'profetizar extáticamente', 'Profetizar en el Hitpael (42 veces), con connotaciones de actividad profética extática o impulsada por el Espíritu — ser arrebatado por el impulso profético más que pronunciar deliberadamente un oráculo. Las escenas paradigmáticas son Números 11:25-27, donde el Espíritu reposa sobre los setenta ancianos y ''profetizan extáticamente'', y 1 Samuel 10:5-13, donde Saúl es sobrecogido entre el grupo de profetas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115497, 'spa', 'Hueco o vacío', 'Hueco, ahuecado o vacío. Éxodo 27:8 y 38:7 lo usan técnicamente en las instrucciones de construcción: el altar de bronce debía hacerse «hueco con tablas» (נָבוּב לֻחֹת), construido como armazón hueca recubierta de planchas de bronce. Jeremías 52:21 describe las enormes columnas de bronce del templo de Salomón como «huecas» (נָבוּב), con paredes de cuatro dedos de espesor. Job 11:12 lo emplea metafóricamente para describir a una persona vacía de entendimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115498, 'spa', 'Nebo (nombre propio)', 'Ciudad moabita asignada a Rubén (Nm 32:3, 38) y monte desde el cual Moisés contempló la Tierra Prometida antes de su muerte (Dt 32:49; 34:1), parte de la cadena de Abarim al este del Jordán (Nm 33:47). La ciudad aparece en oráculos proféticos contra Moab (Is 15:2; Jer 48:1, 22). La deidad babilónica Nebo (Is 46:1) corresponde a un lema distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115501, 'spa', 'Oráculo profético', 'Profecía, declaración u obra profética. Segundo de Crónicas 9:29 cita fuentes: «lo demás de los hechos de Salomón está escrito en la historia de Natán profeta y en la profecía de Ahías silonita»: oráculos escritos auténticos. En 15:8, Asá «cobró ánimo con la profecía de Azarías»: genuino aliento profético. Pero Nehemías 6:12 relata: «entendí que Dios no lo había enviado», desenmascarando una falsa profecía contratada para atemorizarlo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115503, 'spa', 'Nebuzaradán (nombre propio)', 'Nebuzaradán (nombre propio): el oficial militar babilónico Nebuzaradán, siempre identificado por su título ''capitán de la guardia,'' quien sirvió como principal agente de Nabucodonosor en la destrucción y deportación de Jerusalén. Su nombre aparece exclusivamente en 2 Reyes 25 y Jeremías 39-43, 52, enmarcando la caída de Judá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115506, 'spa', 'Nabucodonosor (rey de Babilonia)', 'Nabucodonosor (rey de Babilonia). Nombre propio de Nabucodonosor II, rey de Babilonia. Las 59 apariciones se refieren al mismo gobernante histórico pese a la variación ortográfica menor entre las grafías con resh y con nun. El español ''Nabucodonosor'' sigue la tradición de la Septuaginta griega. Pasajes clave incluyen su conquista de Jerusalén (2 Re 24:1, 10-11) y su papel central en Daniel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115517, 'spa', 'El nombre propio Nabucodonosor (arameo נְבוּכַדְנֶצַּר), rey de Babilonia, que c', 'El nombre propio Nabucodonosor (arameo נְבוּכַדְנֶצַּר), rey de Babilonia, que conquisto Juda, destruyo el primer templo y deporto a su pueblo. Prominente en Daniel (Dn 2:1-4:37), donde interactua con los exiliados judios y finalmente reconoce la soberania de Dios, y en Esdras, donde la confiscacion y devolucion de los utensilios del templo enmarcan la narrativa de la restauracion (Esd 2:1; 5:12, 14; 6:5). Las transliteraciones multilingues -- espanol ''Nabucodonosor,'' frances ''Nebucadnetsar,'' aleman ''Nebukadnezar'' -- preservan tradiciones distintas del nombre babilonico Nabu-kudurri-usur.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115524, 'spa', 'Nombre propio Nabot (hebreo navot), que identifica al jezreelita dueño de una vi', 'Nombre propio Nabot (hebreo navot), que identifica al jezreelita dueño de una viña contigua al palacio de Acab. Las 22 ocurrencias se refieren al mismo individuo en las narrativas de 1 Reyes 21 y 2 Reyes 9. La Septuaginta lo transcribe como Nabouthai, y las traducciones en distintos idiomas conservan el nombre con variaciones mínimas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115529, 'spa', 'Líder y ciudad', 'Noba, un líder manasita y la ciudad que conquistó. Números 32:42 relata: «Noba fue y tomó Kenat y sus aldeas, y la llamó Noba, conforme a su nombre», conteniendo así ambos significados —personal y geográfico— en un solo versículo. Jueces 8:11 emplea el topónimo: «Gedeón subió por el camino de los que habitan en tiendas, al oriente de Noba y Jogbeha», situándola en Transjordania.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115531, 'spa', 'Mirar, contemplar', 'Mirar, contemplar. El sentido básico de mirar visualmente o contemplar: dirigir los ojos hacia algo sin un matiz evaluativo o direccional especial. Dios dice a Abram que mire hacia los cielos y cuente las estrellas (Gn 15:5); la mujer de Lot miró hacia atrás, hacia Sodoma (Gn 19:26); Moisés escondió su rostro, temeroso de mirar a Dios (Éx 3:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115533, 'spa', 'Mirar desde lo alto', 'Mirar desde lo alto. Mirar hacia abajo desde un punto elevado, típicamente de Dios contemplando desde el cielo la tierra o la humanidad. Sal 33:13: ''Desde los cielos miró Jehová; vio a todos los hijos de los hombres.'' También Sal 80:14: ''Mira desde el cielo y contempla.'' La perspectiva divina es el contexto dominante: Dios observa desde arriba con autoridad soberana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115539, 'spa', 'Observar con atención', 'Observar con atención. Mirada sostenida y evaluativa: observar o examinar con escrutinio, preocupación o juicio. Cuando Samuel es enviado a casa de Isaí, Dios le advierte: ''No mires a su apariencia'' (1 Sam 16:7); el verbo aquí lleva el peso de la evaluación. El salmista pide a Dios que ''mire'' (Sal 13:3) y ''observe'' la aflicción (Sal 10:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115542, 'spa', 'Mirar con compasión', 'Mirar con compasión. Mirar a alguien con compasión, preocupación o súplica: una mirada relacional que espera respuesta. Frecuente en oraciones: ''Mira el rostro de tu ungido'' (Sal 84:9); ''Mira, oh Jehová, y observa'' (Lm 1:11; 2:20). Hab 1:5 extiende esto a la mirada de asombro: ''¡Mirad entre las naciones y observad!''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115544, 'spa', 'Mirar (Pi''el intensivo)', 'Mirar (Pi''el intensivo). Una única aparición en Is 5:30 (la forma Pi''el, única en la Biblia hebrea para esta raíz) que describe el acto de mirar sobre la tierra y ver oscuridad y angustia. Las traducciones lo tratan como un acto simple de mirar, pero el tallo Pi''el y el contexto de juicio cósmico lo distinguen. Algunos gramáticos lo consideran un intensivo deliberativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115581, 'spa', 'Padre de Jeroboam I, que aparece únicamente en el patronímico estereotipado ''Jer', 'Padre de Jeroboam I, que aparece únicamente en el patronímico estereotipado ''Jeroboam hijo de Nebat'' a lo largo de Reyes y Crónicas. El nombre probablemente deriva de la raíz navat (''mirar, contemplar''); la LXX lo transcribe Nabath. Sus 25 ocurrencias sirven al programa teológico del historiador deuteronomista: ''Jeroboam hijo de Nebat, que hizo pecar a Israel'' se convierte en el criterio con el que se juzga a cada rey del norte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115582, 'spa', 'Profeta (arameo)', 'Portavoz autorizado divinamente que transmite el mensaje de Dios al pueblo. En Esdras 5:1-2 y 6:14, el término identifica a Hageo y Zacarías como los profetas cuyo aliento motivó la reconstrucción del templo de Jerusalén bajo dominio persa. Los glosarios multilingües son unánimes (profeta, prophète, Prophet), evidenciando que la forma aramea funciona de manera idéntica al hebreo נָבִיא en todos los contextos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115586, 'spa', 'profeta, portavoz divino', 'Persona comisionada por Dios para transmitir mensajes divinamente inspirados, ya sean advertencias, promesas o juicios. El término abarca tanto a los profetas verdaderos (Moisés, Elías, Isaías) como a los falsos, denunciados en Deuteronomio 18:20 y Jeremías. Originalmente distinguido del ''vidente'' (roʾeh, 1 S 9:9), el navíʾ se convirtió en la designación estándar para quienes hablaban con la fórmula ''así dice YHWH''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115629, 'spa', 'Profetisa', 'Mujer reconocida como portadora del don profético, ya sea mediante canto inspirado (Miriam, Éx 15:20), autoridad judicial-oracular (Débora, Jue 4:4), profecía consultiva (Hulda, 2 R 22:14), asociación conyugal con un profeta (esposa de Isaías, Is 8:3), o incluso falsa profecía (Noadías, Neh 6:14). El título es paralelo al masculino נָבִיא e indica genuina autoridad espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115631, 'spa', 'Primogénito de Ismael', 'Nombre propio del primogénito de Ismael y de la tribu pastoril árabe que lleva su nombre. Las genealogías (Gn 25:13; 1 Cr 1:29) lo sitúan como el mayor de los hijos de Ismael. Génesis 28:9 y 36:3 vinculan a Esaú con este linaje por matrimonio. Isaías 60:7 empareja a Nebaiot con Cedar como pueblos cuyos rebaños servirán en adoración escatológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115633, 'spa', 'Necedad y deshonra', 'Actuar neciamente (Qal) o tratar con desprecio y deshonra (Piel), abarcando desde la locura personal hasta la humillación pública. Proverbios 30:32 advierte contra la autoexaltación necia. El Piel comporta mayor fuerza: Deuteronomio 32:15 describe a Israel menospreciando a su Hacedor; Miqueas 7:6 retrata a un hijo deshonrando a su padre; Nahúm 3:6 muestra a Dios afrentando a Nínive.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115634, 'spa', 'Marchitarse, desvanecerse (vegetación)', 'Marchitarse, desvanecerse (vegetación): sentido botánico central de marchitarse, desvanecerse y caer, que abarca 16 de 20 apariciones. Plantas, flores, hojas y hierba pierden su vitalidad y se desploman. En el Salmo 1:3 la hoja del justo ''no se marchitará'' (יִבּוֹל), mientras que en Isaías 40:7-8 la hierba se seca y la flor se marchita ante el soplo del SEÑOR.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115638, 'spa', 'Desmoronarse, desintegrarse', 'Desmoronarse, desintegrarse: extensión rara más allá de la decadencia orgánica hacia la desintegración física — desmoronamiento estructural en vez de marchitamiento botánico. En Job 14:18 una montaña cae y se desmorona, y una roca es movida de su lugar. Este sentido muestra que el alcance semántico de la palabra se extiende a cualquier colapso irreversible de forma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115644, 'spa', 'Desgastarse, agotarse', 'Desgastarse, agotarse: sentido de agotamiento humano por sobreesfuerzo, atestiguado en 3 apariciones. En Éxodo 18:18 Jetro advierte a Moisés —usando tanto infinitivo absoluto como imperfecto— ''ciertamente te agotarás'' (נָבֹל תִּבֹּל). Isaías 64:6 lo extiende comunitariamente: ''todos nos marchitamos como una hoja,'' aplicando la metáfora vegetal a la fragilidad espiritual colectiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115650, 'spa', 'Vasija, tinaja', 'Una vasija de barro, cántaro o tinaja — un recipiente de cerámica en lugar de cuero. Isaías 30:14 habla de la ''quiebra de un nevel de alfarero'', y Lamentaciones 4:2 compara a los nobles hijos de Sion con nivle-cheres (''vasijas de barro''), subrayando su reducción a material sin valor. Jeremías 13:12 usa la tinaja como imagen parabólica del juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115651, 'spa', 'Odre, pellejo', 'Un recipiente de cuero — odre de vino o de agua hecho de piel de animal. La expresión nevel yayin (''odre de vino'') aparece en 1 Samuel 1:24, 10:3 y 2 Samuel 16:1 para el transporte práctico de vino. Job 38:37 extiende esta imagen metafóricamente a las nubes como ''odres del cielo'' (nivle shamayim), vertiendo lluvia sobre la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115659, 'spa', 'Instrumento musical de cuerdas (probablemente un arpa con caja de resonancia abo', 'Instrumento musical de cuerdas (probablemente un arpa con caja de resonancia abombada) empleado en el culto del templo, ceremonias reales y actividad profética. Se distingue del más sencillo kinnor y suele nombrarse junto a él. Central en la adoración levítica del templo (1 Cr 15:16, 20, 28; 25:1, 6; 2 Cr 5:12; 29:25), introducido en el grupo de profetas que Saúl encontró (1 S 10:5), y tocado ante el Arca por David y todo Israel (2 S 6:5; 1 Cr 13:8). Los profetas condenaron su uso en la indulgencia frívola (Am 5:23; 6:5; Is 5:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115674, 'spa', 'Necio, persona insensata', 'Necio, persona insensata: persona caracterizada por una ceguera moral y espiritual voluntaria, no por mera ignorancia. El término conlleva connotaciones de impiedad vergonzosa y presunción vil. En Deuteronomio 32:6 describe la ingratitud de Israel hacia Dios; en el Salmo 74:18 señala a quienes blasfeman el nombre divino. Usado sustantivamente para la persona culpablemente necia (2 Sam 3:33; Is 32:5-6; Job 2:10), se opone marcadamente al noble y al prudente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115686, 'spa', 'El nombre propio Nabal (del hebreo נָבָל, ''necio, insensato''), que designa al gr', 'El nombre propio Nabal (del hebreo נָבָל, ''necio, insensato''), que designa al grosero esposo de Abigail, originario de la región de Carmel. Las 22 apariciones abarcan desde 1 Samuel 25 hasta 2 Samuel 3:3. El juego etimológico es central en la narrativa: la propia Abigail explica que su nombre significa necedad (נְבָלָה). Las traducciones transliteran uniformemente el nombre; en español, francés y alemán se usa Nabal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115690, 'spa', 'Cadáver humano', 'Cadáver humano. El cuerpo muerto de un ser humano, frecuentemente en contextos de muerte violenta, exposición o entierro deshonroso. Con 25 apariciones, este sentido tiene peso en narraciones de juicio divino y consecuencias de batalla. El cadáver del profeta en el camino (1 Re 13:22-30) y la maldición de Dt 28:26 (''tu cadáver será alimento para toda ave'') emplean נְבֵלָה para transmitir el horror de la muerte sin sepultura digna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115692, 'spa', 'Cuerpo muerto de animal', 'Cuerpo muerto de animal. El cuerpo muerto de un animal, central en la legislación levítica de pureza que rige lo que contamina por contacto. Con 23 apariciones concentradas en Lv 5:2, 7:24, 11:8-40, este sentido ancla la taxonomía de lo puro e impuro en la Torá: tocar la נְבֵלָה de una criatura impura acarrea impureza, y aun un animal puro que muere naturalmente se convierte en fuente de contaminación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115712, 'spa', 'infamia, vileza atroz', 'Insensatez moral manifestada como conducta ultrajante y vergonzosa que viola las normas comunitarias y pactuales. Casi siempre aparece en la frase estereotipada ''cometer nevalah en Israel'', señalando actos — especialmente delitos sexuales (Gn 34:7, la violación de Dina; Jue 19:23–24; 2 S 13:12, Amnón y Tamar) y conducta que quebranta el pacto (Jos 7:15) — como socialmente intolerables.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115721, 'spa', 'Proferir, derramar palabras', 'Derramar discurso, alabanza o declaración (Hifil metafórico). El uso bíblico predominante: los días ''derraman'' palabra (Sal 19:2), el salmista ''profiere'' enigmas (Sal 78:2) y los labios ''rebosan'' de alabanza al aprender los estatutos de Dios (Sal 119:171). Negativamente, los necios y malvados ''vomitan'' necedad y arrogancia (Sal 59:7, 94:4, Prov 15:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115722, 'spa', 'Fluir, brotar', 'Fluir o brotar naturalmente como agua (Qal). Aparece únicamente en Proverbios 18:4, donde ''las palabras de la boca del hombre son aguas profundas, arroyo que fluye, fuente de sabiduría''. Este es el anclaje semántico del cual derivan los usos metafóricos referidos al habla — el manantial que alimenta el río de la expresión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115729, 'spa', 'Fermentar, heder', 'Causar fermentación, putrefacción o mal olor (Hifil causativo con resultado negativo). Eclesiastés 10:1 describe moscas muertas que hacen que el ungüento del perfumista ''burbujee'' y hieda. Este sentido conserva el núcleo efervescente de la raíz pero lo redirige del flujo saludable hacia la corrupción — una inversión notable del desbordamiento vital.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115733, 'spa', 'lado sur, uso transicional', 'Uso transicional o ambiguo en el que néguev designa el lado sur de una estructura o un límite, conservando ecos de la región geográfica. Referencias como Éx 27:9, 36:23 y 38:9 describen el ''lado néguev'' del tabernáculo, y Nm 34:3 traza el límite meridional. Estas ocurrencias se sitúan entre la dirección cardinal pura y la identidad regional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115734, 'spa', 'sur, punto cardinal', 'El punto cardinal sur o la dirección hacia el sur, empleado para la orientación geográfica general sin referencia específica a la región del Néguev. Aparece en la construcción del tabernáculo (Éx 26:18; 27:9; 36:23; 38:9; 40:24), las descripciones de límites tribales (Jos 15:1; 18:5) y expresiones direccionales como ''norte y sur'' (Gn 13:14; 28:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115737, 'spa', 'la región del Néguev', 'El Néguev como designación geográfica propia: la región árida y semidesértica al sur de las tierras altas de Judá, que se extiende aproximadamente desde las colinas al sur de Hebrón hasta el desierto de Cadés. Abraham reside allí (Gn 20:1; 24:62), los espías entran a la tierra por esta zona (Nm 13:17, 22) y se subdivide en distritos con nombre: el Néguev de Judá, de los jerahmeelitas, de los ceneos (1 S 27:10; 30:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115765, 'spa', 'contar, informar', 'Significado nuclear del Hifil: contar, relatar o informar a alguien de hechos, sucesos o noticias en contextos interpersonales ordinarios. Este sentido instrumental representa la mayoría de las ocurrencias. Gn 9:22 (Cam informa a sus hermanos), Gn 14:13 (un fugitivo informa a Abram) y Gn 29:12 (Jacob cuenta a Raquel) ilustran el registro narrativo neutro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115767, 'spa', 'ser informado (Hofal)', 'El Hofal (pasivo del Hifil): ser informado, recibir noticia de algo. La fórmula ''y le fue contado a X'' reaparece como bisagra narrativa — Gn 22:20 (se le contó a Abraham), Gn 27:42 (se le contó a Rebeca), Gn 38:13 (se le contó a Judá) — introduciendo consistentemente giros decisivos en la trama.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115768, 'spa', 'declarar, proclamar', 'Sentido elevado del Hifil: declarar, proclamar o anunciar pública y formalmente, a menudo en contextos proféticos, litúrgicos o reales. El tránsito del relato privado a la proclamación pública se refleja en el español anunciar/declarar. Dt 5:5 (Moisés declarando las palabras de Dios), Dt 26:3 (la declaración solemne del peregrino) y los anuncios proféticos en Isaías ejemplifican este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115774, 'spa', 'mensajero, informante', 'El participio Hifil empleado como sustantivo: un mensajero, informante o heraldo — alguien definido por el acto de traer noticias. Este uso nominal aparece en coyunturas narrativas dramáticas: el informante en Gn 41:24, los mensajeros que reportan desenlaces de batalla en 2 S 1:5-13. La función de nombre de agente es uniforme en todas las lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115856, 'spa', 'revelar, descubrir', 'Sentido del Hifil que enfatiza la revelación o el descubrimiento de una verdad oculta. En Sal 19:1, los cielos ''declaran'' la gloria de Dios — haciendo visible lo que trasciende la percepción ordinaria —, mientras que Pr 29:24 habla de un cómplice del ladrón que no ''revela'' nada. El énfasis recae en desvelar lo encubierto, no en transmitir noticias cotidianas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115926, 'spa', 'denunciar, delatar', 'Uso especializado del Hifil con fuerza hostil o acusatoria: denunciar o delatar a alguien. En Jer 20:10, los enemigos de Jeremías susurran ''¡denunciémoslo!'', y Job 17:5 advierte contra quien delata a sus amigos. Los contextos adversariales distinguen claramente este sentido del relato neutro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115942, 'spa', 'confesar', 'Una única ocurrencia (Sal 38:18) donde nagad adquiere un registro confesional — ''declararé mi iniquidad''. El paralelismo del versículo con la angustia por el pecado sugiere una aplicación confesional especializada del significado nuclear de ''dar a conocer'', dirigida hacia dentro en vez de hacia fuera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115959, 'spa', 'delante de, en presencia de', 'Sentido adverbial/preposicional primario de estar al frente de alguien o en su presencia, con la implicación de que la persona es consciente y puede ver lo que tiene delante. Gn 31:32 (''delante de nuestros parientes, identifica lo que es tuyo''), Éx 34:10 (''delante de todo tu pueblo haré maravillas'') y Sal 78:12 anclan este sentido de visibilidad directa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115960, 'spa', 'enfrente, mirando hacia', 'Sentido espacial de estar directamente enfrente o mirando hacia algo, con énfasis en la orientación frontal más que en la mera proximidad. Éx 19:2 (Israel acampó ''frente al monte''), Jos 3:16 (las aguas se detuvieron ''enfrente de'' Adam) y Jos 8:33 (la mitad de Israel ''frente al'' monte Guerizín, la otra mitad ''frente al'' Ebal) ilustran la precisión direccional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115964, 'spa', 'lejos de ante', 'Con el prefijo min (minnegued o min-négued), sentido de alejamiento o separación de la presencia frontal de alguien. Sal 31:22 (''dije en mi angustia: he sido cortado de delante de tus ojos'') y 1 S 26:20 (''no caiga mi sangre en tierra lejos de la presencia del SEÑOR'') expresan la dolorosa remoción de la presencia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115965, 'spa', 'a distancia, desde enfrente', 'Sentido de estar a distancia o desde el lado opuesto manteniendo la orientación frontal — observación remota desde el otro lado de un espacio. Gn 21:16 es paradigmático: Agar se sienta ''a distancia, enfrente'' (minnegued), sin querer ver morir a Ismael. Nm 2:2 posiciona a las tribus acampadas ''a distancia, frente a'' la tienda del encuentro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115972, 'spa', 'correspondiente a, contraparte', 'Sentido relacional distintivo que significa ''correspondiente a, que complementa, contraparte de'' — no meramente espacial, sino que describe complementariedad esencial. Solo dos ocurrencias, ambas en Gn 2:18, 20: Dios dice ''le haré una ayuda kenegdó'' — una compañera que le hace frente como su par. La expresión trasciende la proximidad física para evocar igualdad y correspondencia profunda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115980, 'spa', 'contra, en oposición', 'Sentido adversativo en el que néged pasa de la orientación espacial frontal a la oposición hostil — ''contra'' más que simplemente ''delante de''. Pr 21:30 (''no hay sabiduría, ni inteligencia, ni consejo contra el SEÑOR'') y Job 10:17 (''renuevas tus testigos contra mí'') muestran con claridad el matiz de confrontación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115998, 'spa', 'Brillar, dar luz', 'Brillar o hacer resplandecer la luz, abarcando el Qal intransitivo (la luz resplandece por sí misma, Isa 9:2; Job 22:28) y el Hifil causativo (Dios iluminando la oscuridad humana, 2 Sam 22:29 / Sal 18:28). El verbo posee fuerte resonancia teológica: la luz divina irrumpe en las tinieblas del hombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116004, 'spa', 'Resplandor, fulgor, esplendor', 'Resplandor, fulgor, esplendor: brillo radiante que emana de una fuente luminosa, especialmente divina o celestial. Este sentido cubre la gran mayoría de las apariciones (18 de 19), incluyendo el resplandor de la teofanía (2 Sam 22:13, Sal 18:12), las visiones de Ezequiel de la gloria divina (Ez 1:4, 27-28; 10:4), el brillo de la luna y las estrellas (Is 60:19; Jl 2:10; 4:15) y la luminosidad profética de Sion (Is 60:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116009, 'spa', 'Luz del alba, radiancia del amanecer', 'Luz del alba, radiancia del amanecer: el resplandor específico del alba o la aurora — la radiancia creciente que caracteriza el romper del día. Atestiguado una vez en Proverbios 4:18, donde el camino de los justos se compara a ''la luz de la aurora que va en aumento hasta que el día es perfecto.'' La fuerza metafórica distingue este sentido temporal-natural del resplandor más amplio del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116020, 'spa', 'Cornear, embestir', 'Qal básico: cornear literalmente, un animal que embiste con sus cuernos. Las leyes sobre el buey que cornea en Éxodo 21:28-32 emplean exclusivamente este sentido — un buey que acornea a una persona (hebreo yiggach). Refleja la violencia animal directa que requiere remedio legal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116021, 'spa', 'Acornear con fuerza', 'Piel intensivo: cornear vigorosa o repetidamente, usado figuradamente para la conquista militar y la fuerza abrumadora. José como un toro salvaje que acornea pueblos hasta los confines de la tierra (Deut 33:17); los cuernos de hierro de Sedequías simbolizando la victoria (1 Re 22:11). El árabe nataha (''topar'') ancla la imagen de embestida con cuernos en otras lenguas semíticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116024, 'spa', 'Embestirse mutuamente', 'Hitpael reflexivo-recíproco: arremeter el uno contra el otro, trabar combate mutuo. Se encuentra únicamente en Daniel 11:40, donde el rey del Sur ''embiste contra'' el rey del Norte. El Hitpael transmite la fuerza recíproca de dos potencias colisionando como bestias en guerra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116029, 'spa', 'Una persona que ostenta autoridad politica, militar o religiosa -- un gobernante', 'Una persona que ostenta autoridad politica, militar o religiosa -- un gobernante, comandante, principe o lider oficialmente designado. Atestiguado 43 veces, este sentido abarca todo el espectro del liderazgo israelita: Saul ungido como nagid (1 S 9:16, 10:1), David designado por Dios (1 S 13:14; 2 S 5:2; 7:8), Salomon instalado (1 Cr 29:22), y supervisores del templo (2 Cr 35:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116044, 'spa', 'Un uso abstracto o adjetival que significa ''cosas nobles'' o ''asuntos excelentes,', 'Un uso abstracto o adjetival que significa ''cosas nobles'' o ''asuntos excelentes,'' encontrado unicamente en Proverbios 8:6, donde la Sabiduria personificada declara: ''Escuchad, porque hablare negidim.'' Aqui el plural pasa de personas con autoridad a la calidad del discurso mismo -- cosas que son dignas, nobles y con peso de autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116051, 'spa', 'instrumentos de cuerda', 'Música interpretada con instrumentos de cuerda, o los propios instrumentos. Este sentido predomina en las inscripciones de los Salmos — binginot aparece como indicación litúrgica en los Salmos 4, 6, 54, 55, 61, 67 y 76, y en Habacuc 3:19. Isaías 38:20 emplea el posesivo ''mis instrumentos de cuerda'' en el cántico de recuperación de Ezequías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116053, 'spa', 'canción de burla', 'Canción o melodía, frecuentemente con connotación peyorativa como mofa o canción de escarnio. Job 30:9 es el caso paradigmático: ''he llegado a ser su canción de burla'', en paralelo con milla (''refrán''). Lamentaciones 3:14 hace eco de la misma humillación, y el Salmo 69:12 añade que los borrachos cantan canciones sobre el que sufre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116059, 'spa', 'música en general', 'Música en sentido general o abstracto — la práctica cultural global de la interpretación musical, más que instrumentos o canciones específicas. En Lamentaciones 5:14, los ancianos abandonaron la puerta y los jóvenes ''su música'', lamentando el colapso de todo un modo de vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116060, 'spa', 'tocar instrumento de cuerda', 'Tocar o hacer música con un instrumento de cuerda (formas verbales e infinitivos del Piel). En 1 Samuel 16:16–23, David toca la lira (כִּנּוֹר) para apaciguar a Saúl. Isaías 38:20 emplea la primera persona del plural ''tocaremos'' (נְנַגֵּן) en el cántico de acción de gracias de Ezequías. Ezequiel 33:32 compara al profeta con alguien que toca con destreza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116067, 'spa', 'músico, instrumentista', 'Músico, tañedor o intérprete — el participio usado sustantivamente como nombre de agente. En 2 Reyes 3:15, Eliseo dice ''traedme un músico'' (הַמְנַגֵּן), y mientras el tañedor interpreta, la mano del Señor viene sobre el profeta. El Salmo 68:25 sitúa a ''los músicos'' (נֹגְנִים, participio Qal) en una procesión del templo junto a cantores y doncellas con panderos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116072, 'spa', 'tocar físicamente (Qal)', 'Sentido Qal de contacto físico — poner las manos sobre una persona, objeto o elemento sagrado. Abarca el contacto táctil general, el toque prohibido o tabú (el árbol en Edén, los utensilios santos, las cosas impuras) y los contextos de pureza ritual. Gn 3:3 (''Dios dijo: no lo tocaréis''), Éx 29:37 (''todo lo que toque el altar será santificado'') anclan este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116078, 'spa', 'alcanzar, llegar (Hifil/Qal)', 'Sentido Qal e Hifil intransitivo de alcanzar un destino, llegar a un lugar o extenderse hasta un punto en el espacio o el tiempo. El árabe balagha y wasala (alcanzar, llegar) emplean raíces diferentes de tocar o golpear, confirmando un dominio semántico distinto. Gn 28:12 (la escalera ''que llegaba'' al cielo), 2 Cr 3:11 (las alas de los querubines ''alcanzaban'' la pared) y 1 S 14:9 ilustran esta acepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116097, 'spa', 'ser herido, ser derrotado', 'Sentidos del Nifal reflexivo-pasivo, Pual intensivo pasivo y participio pasivo Qal: ser herido, golpeado o derrotado. Is 53:4 tiene importancia teológica capital: el Siervo Sufriente es ''herido, golpeado por Dios y afligido''. Sal 73:14 completa la imagen del inocente que sufre una aflicción que parece inmerecida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116098, 'spa', 'hacer llegar, causar (Hifil)', 'Sentido causativo del Hifil: hacer que algo alcance, traer algo sobre alguien o causar que llegue a su destino. Éx 12:22 (mojando el hisopo y ''haciéndolo tocar'' el dintel), Is 25:12 (''derribará hasta la tierra, hasta el polvo'') y Lm 2:2 (''derribó hasta el suelo el reino'') muestran a un agente que dirige el contacto o el arribo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116108, 'spa', 'golpear, afligir, plagar', 'Sentido intensivo del Piel y ciertos usos del Qal que significan golpear, afligir o plagar, donde el contacto es dañino y frecuentemente administrado por Dios. Gn 12:17 (''el SEÑOR hirió la casa de Faraón con grandes plagas'') y 2 R 15:5 (''el SEÑOR hirió al rey'') muestran la dimensión de castigo divino. El árabe daraba (golpear) emplea una raíz completamente diferente de tocar o alcanzar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116117, 'spa', 'juntar, colindar', 'Ocurrencia única en Is 5:8 donde el verbo aparece con el sentido de juntar o hacer colindar — los que ''juntan'' casa con casa y campo con campo hasta no dejar espacio. Se trata de una lectura de contacto espacial: presionar propiedades unas contra otras hasta borrar los límites, una denuncia profética de la acumulación de tierras por los poderosos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116162, 'spa', 'Enfermedad cutánea', 'Enfermedad cutánea. El término técnico levítico para una mancha enferma o erupción cutánea sometida al examen sacerdotal. Levítico 13-14 usa נֶגַע docenas de veces para marcas en la piel, vestiduras y paredes de casas: un vocabulario diagnóstico sin verdadero paralelo en las culturas circundantes. El sacerdote no sana; clasifica y aísla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116164, 'spa', 'Plaga, calamidad divina', 'Plaga, calamidad divina. Plaga o calamidad enviada por Dios como juicio o castigo correctivo sobre personas o naciones. Las grandes plagas sobre la casa de Faraón (Gn 12:17) y la plaga final culminante del Éxodo (Éx 11:1) ejemplifican este sentido. La oración de Salomón en el templo (1 Re 8:37-38) empareja נֶגַע con מַחֲלָה (''enfermedad''), y el salmista promete que ninguna plaga se acercará a la morada del fiel (Sal 91:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116165, 'spa', 'Golpe, herida', 'Golpe, herida. Golpe, herida o lesión física infligida por una persona a otra. Deuteronomio 17:8 y 21:5 enumeran נֶגַע junto con רִיב (''disputa legal'') como asuntos que requieren adjudicación sacerdotal. Proverbios 6:33 advierte al adúltero que hallará herida y deshonra. Isaías 53:8 aplica el término al sufrimiento del Siervo, elevando la herida física a dimensión expiatoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116179, 'spa', 'Azotes, castigo', 'Azotes, castigo. Azotes o golpes administrados como castigo correctivo. En 2 Samuel 7:14, Dios promete disciplinar al heredero de David ''con azotes de hombres'', emparejando נֶגַע con שֵׁבֶט (''vara''). Salmo 89:32 hace eco de esta disciplina pactual. Se distingue de la mera herida o enfermedad como castigo medido en lugar de aflicción aleatoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116183, 'spa', 'Golpear, herir', 'Golpear, herir. Golpear o herir a alguien con daño grave, a menudo fatal, en el Qal activo. Dios golpea a Egipto en la Pascua (Éx 12:23, 27) y a individuos bajo juicio (1 Sam 25:38; 2 Cr 21:18). El sujeto es típicamente Dios o un agente investido de poder divino, y el golpe conlleva fuerza deliberada e irrevocable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116184, 'spa', 'Ser derrotado, ser dispersado', 'Ser derrotado, ser dispersado. Ser derrotado o puesto en fuga en batalla: el Nifal pasivo, con 23 apariciones. Se advierte a Israel que será ''golpeado ante sus enemigos'' si desobedece (Dt 28:25), y que los enemigos huirán por siete caminos cuando Israel obedezca (Dt 28:7). El español ''derrotado/derrotados'' capta el registro militar con más precisión que un genérico ''golpeado''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116205, 'spa', 'Tropezar, chocar contra', 'Tropezar, chocar contra. Tropezar o dar con el pie contra un obstáculo, a veces con matices figurados de caída espiritual. Salmo 91:12 promete protección angélica ''para que no tropieces con tu pie en piedra'': el versículo citado durante la tentación de Jesús. Proverbios 3:23 asegura al sabio que ''tu pie no tropezará''. Jeremías 13:16 extiende esto a la metáfora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116220, 'spa', 'Plaga, azote divino', 'Golpe mortal o plaga enviada como juicio divino, usado exclusivamente en textos sacerdotales y afines. En Éxodo 12:13, Dios declara que la plaga destructora (נֶגֶף) no tocará a Israel durante la Pascua; en Éxodo 30:12, un censo sin rescate arriesga la plaga; Números 8:19 advierte del castigo si personas no autorizadas se acercan al santuario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116222, 'spa', 'Tropiezo, golpe', 'Golpe o tropiezo, usado de manera singular en Isaías 8:14, donde Dios se convierte en ''piedra de tropiezo'' (אֶבֶן נֶגֶף) y ''roca de caída'' para ambas casas de Israel. La imagen no es de plaga epidémica sino de un obstáculo contra el cual el pie golpea y la persona cae. El paralelo con צוּר מִכְשׁוֹל (''roca de tropiezo'') confirma este sentido metafórico distintivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116223, 'spa', 'Ser derramado, fluir', 'Sentido Nifal pasivo de ser vertido o fluir — líquido derramado sin posibilidad de recuperación. En 2 Samuel 14:14 la mujer sabia de Tecoa compara la mortalidad humana con ''agua derramada en tierra que no puede recogerse'', y en Lamentaciones 3:49 el ojo del poeta ''se derrama sin cesar''. Job 20:28 lo aplica a la riqueza del impío que se disipa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116224, 'spa', 'Derramar, verter', 'Sentido Hifil causativo de derramar activamente o hacer fluir algo. Dios vierte el vino de su furor (Sal 75:8), el profeta pide a Dios que derrame a sus enemigos a espada (Jer 18:21) y en Miqueas 1:6 Dios derramará las piedras de Samaria al valle. El agente es siempre poderoso — divino o profético — y el derramamiento constituye un acto de juicio o demolición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116227, 'spa', 'Extender, estirar', 'Sentido Nifal poco frecuente en Salmo 77:2, donde el salmista dice ''mi mano se extendió en la noche y no se entorpeció''. Aquí el verbo parece significar ''ser extendido'' o ''desplegado'', apartándose de su semántica líquida habitual. Algunos eruditos enmiendan ''mano'' por ''ojo'' para restaurar el sentido de llanto, pero el texto recibido sugiere una extensión del fluir hacia afuera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116231, 'spa', 'Entregar, abandonar', 'Extensión figurada del Hifil que significa entregar o abandonar personas a la destrucción, como si se las vertiera cual agua. En Ezequiel 35:5 Edom ''derramó'' a los hijos de Israel a espada, y en Salmo 63:10 los impíos serán ''derramados por filo de espada''. La imagen física del líquido vertido se convierte en metáfora de transferencia violenta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116233, 'spa', 'Capataz, conductor de esclavos — 8 apariciones, todas usando el participio Qal נ', 'Capataz, conductor de esclavos — 8 apariciones, todas usando el participio Qal נֹגֵשׂ como sustantivo. Es el sentido por excelencia del Éxodo: los capataces egipcios que agotan a los trabajadores israelitas (Éx 3:7; 5:6, 10, 13, 14) y la vara del opresor quebrada en Job 3:18, cuando los fatigados hallan descanso en la muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116234, 'spa', 'Opresor, tirano en un sentido político o social general — 6 apariciones donde el', 'Opresor, tirano en un sentido político o social general — 6 apariciones donde el participio Qal se extiende más allá del trabajo forzado hacia una tiranía más amplia. La profecía de Isaías de que la vara del opresor será quebrada (Is 9:4), la reversión donde los antiguos cautivos ''dominarán a sus opresores'' (Is 14:2), y la promesa de Zacarías de que ''ningún opresor pasará más por ellos'' (Zac 9:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116235, 'spa', 'Ser oprimido, angustiado (Nifal pasivo) — 4 apariciones donde el sujeto sufre la', 'Ser oprimido, angustiado (Nifal pasivo) — 4 apariciones donde el sujeto sufre la presión en lugar de infligirla. Los israelitas en Micmas estaban ''acosados'' por los filisteos (1 S 13:6); las tropas de Saúl estaban ''afligidas'' por su juramento precipitado (1 S 14:24); en Isaías 53:7, el Siervo Sufriente ''fue oprimido'' — uno de los pasivos más significativos teológicamente del Antiguo Testamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116240, 'spa', 'Exigir, demandar el pago de deudas o tributo — 5 apariciones en formas verbales ', 'Exigir, demandar el pago de deudas o tributo — 5 apariciones en formas verbales finitas del Qal. Deuteronomio 15:2-3 legisla la remisión sabática: un acreedor ''no exigirá'' de su prójimo, pero ''podrá exigir'' del extranjero. En 2 Re 23:35, Joacim ''exigió'' plata y oro del pueblo para pagar el tributo del faraón. Daniel 11:20 profetiza un ''exacto'' que envía agentes por la gloria del reino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116253, 'spa', 'acercarse, aproximarse (Qal)', 'Sentido intransitivo básico del Qal: moverse hacia alguien o algo, acercarse, aproximarse física o relacionalmente. Gn 18:23 (Abraham se acercó y dijo), 19:9 (¡atrás! / ¡acércate!), 27:21-26 (Isaac dijo: ''acércate, por favor'') muestran el acercamiento simple. Es el sentido fundacional del verbo, presente tanto en el discurso narrativo como en el legal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116256, 'spa', 'presentar, ofrecer (Hifil cúltico)', 'Hifil en sentido cúltico especializado: presentar u ofrecer en un contexto sacrificial o ritual — traer una ofrenda, don o sacrificio ante Dios. Jue 6:19 (Gedeón sacó la ofrenda), 1 S 13:9, 14:34, 15:32 (traed el holocausto, traed los bueyes, traed al rey Agag) ilustran la presentación ritual. Se distingue del Hifil general por su marco litúrgico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116257, 'spa', 'hacer acercar, traer (Hifil)', 'Hifil en su fuerza causativa general: hacer que alguien o algo se acerque, traer cerca. Gn 27:25 (tráemelo), 48:10, 13 (José acercó a sus hijos a Israel), Éx 21:6 (llévalo a la puerta) ilustran el acercamiento de personas u objetos. Es más amplio que el uso cúltico: cubre todo acto de traer algo a la proximidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116261, 'spa', 'presentarse, acercarse (Nifal)', 'Nifal medio o reflexivo: acercarse o presentarse de manera formal o por propia iniciativa, frecuentemente ante Dios, un líder o para juicio. Gn 33:7 (Lea se acercó con sus hijos), Éx 19:22, 20:21, 24:2 (los sacerdotes que se acercan al SEÑOR), 34:32 (Moisés los llamó y se acercaron) muestran autopresentación o aproximación formal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116283, 'spa', 'ser acercado, ser ofrecido (Hofal)', 'Hofal pasivo: ser acercado o ser ofrecido/presentado, generalmente en contextos formales o cúlticos. 2 S 3:34 (tus manos no fueron atadas, tus pies no fueron puestos en grillos) y Mal 1:11 (una ofrenda pura es presentada a mi nombre) muestran la pasivización. Es la conjugación menos frecuente de este verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116301, 'spa', 'congregarse, acercarse juntos', 'Is 45:20 — el contexto (reuníos, congregaos, acercaos juntos, sobrevivientes de las naciones) sugiere una convocatoria o reunión. La contribución semántica específica de נָגַשׁ es el acercamiento espacial colectivo, aunque sin mayor especificación más allá del movimiento conjunto hacia un punto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116303, 'spa', 'alcanzar, dar alcance', 'Am 9:13 — ''el arador alcanzará al segador'' — el verbo sugiere sucesión rápida o la acción de dar alcance, extendiendo el acercamiento espacial a la proximidad temporal o la urgencia. Puede tratarse de una extensión metafórica de la cercanía espacial a la temporal: las estaciones se solapan por la abundancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116309, 'spa', 'avanzar, presionar (Qal)', 'Subsentido del Qal que enfatiza el movimiento hacia adelante deliberado o agresivo — avanzar, presionar, frecuentemente en contextos militares o de confrontación. Gn 19:9 (presionaron con fuerza contra Lot) y Jer 46:3 (preparad escudo y rodela, avanzad para la batalla) muestran el matiz de determinación y vigor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116318, 'spa', 'sobrevenir, confrontar', 'Am 9:10 — ''el desastre no nos sobrevendrá ni nos confrontará'' — similar al sentido 8, el verbo expresa la llegada inminente o la confrontación inevitable. Las dos ocurrencias en Amós podrían formar un subsentido de acercamiento temporal o inexorable, distinto de la proximidad espacial voluntaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116338, 'spa', 'Montón, cúmulo', 'Un montón o cúmulo, referido a las aguas sobrenaturalmente amontonadas en los eventos de salvación de Israel. En el Mar Rojo las aguas ''se detuvieron como montón'' (Éx 15:8) y en el Jordán ''se levantaron en un solo montón'' (Jos 3:13, 16). Los salmos evocan esta imagen en adoración (Sal 33:7; 78:13), marcando el poder divino sobre las aguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116341, 'spa', 'Impulsar, mover, incitar (Qal)', 'Impulsar, mover, incitar (Qal): despertar, impulsar o mover el corazón o el espíritu de una persona a la acción (Qal activo). Éxodo 25:2 instruye a Moisés a recibir contribuciones de ''todo aquel a quien su corazón impulse'' (יִדְּבֶנּוּ לִבּוֹ), y 35:21 describe a aquellos ''a quienes su corazón estimuló'' y ''a quienes su espíritu impulsó'' a traer ofrendas para el tabernáculo (Éx 35:29). Mientras el sentido 1 enfatiza la acción voluntaria resultante, este sentido capta el impulso interior previo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116342, 'spa', 'Ofrecerse voluntariamente (Hitpael)', 'Ofrecerse voluntariamente (Hitpael): ofrecerse a sí mismo o sus posesiones libre y voluntariamente, sin coacción externa (Hitpael reflexivo). El cántico de victoria de Débora alaba al pueblo que se ofreció para la guerra (Jue 5:2, 9). Los preparativos de David para el templo se convierten en una fiesta de generosidad voluntaria cuando líderes, oficiales y el pueblo ''ofrecieron voluntariamente'' (1 Cr 29:5-9, 17). Esdras 2:68 registra a los exiliados que regresaron y se ofrecieron para la reconstrucción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116355, 'spa', 'Ofrenda voluntaria', 'Ofrecerse voluntariamente o dar de buena gana, especialmente para fines religiosos. Esdras 7:13 emplea el participio: todo israelita en Babilonia «que se ofrezca voluntariamente» (מִתְנַדַּב) a regresar a Jerusalén puede hacerlo. El versículo 15 describe el apoyo económico: la plata y el oro que el rey y sus consejeros «ofrecieron voluntariamente» (הִתְנַדָּבוּ) al Dios de Israel. El versículo 16 registra también las ofrendas voluntarias del pueblo y los sacerdotes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116356, 'spa', 'Nadab (nombre propio)', 'Nadab (nombre propio): nombre personal Nadab (hebreo Nadav, ''generoso, noble''), que identifica a cuatro individuos distintos: (a) el primogénito de Aarón, ordenado sacerdote pero fulminado por ofrecer fuego extraño (Éx 6:23; Lv 10:1; Nm 26:60-61); (b) el hijo de Jeroboam I y rey efímero de Israel (1 R 15:25-31); (c) un jeramelita (1 Cr 2:28, 30); (d) un gabaonita (1 Cr 8:30; 9:36).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116358, 'spa', 'El sentido cúltico principal', 'El sentido cúltico principal: una ofrenda sacrificial voluntaria presentada a Dios más allá de lo que la ley exige, abarcando holocaustos, ofrendas de cereal y otros dones. Aparece en Levítico, Deuteronomio y Crónicas en diversas formas. El énfasis hebreo recae sobre la voluntariedad más que sobre el tipo de ofrenda. Pasaje clave: Éxodo 35:29, donde los israelitas trajeron sus ofrendas con corazón dispuesto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116362, 'spa', 'Un único uso metafórico en el Salmo 68', 'Un único uso metafórico en el Salmo 68:9, donde גֶּשֶׁם נְדָבוֹת significa ''lluvia generosa'' o ''lluvia abundante'', extendiendo la noción de generosidad voluntaria del ámbito cúltico a la provisión pródiga de Dios en la naturaleza. El término ''abundancia'' capta el desplazamiento semántico de don voluntario a derramamiento copioso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116368, 'spa', 'El sentido adverbial abstracto de actuar libre y voluntariamente, sin coacción', 'El sentido adverbial abstracto de actuar libre y voluntariamente, sin coacción. En Oseas 14:4, el amor de Dios se derrama נְדָבָה — de manera libre e incondicional. En el Salmo 54:6, el salmista ofrece alabanza desde un corazón no forzado. El paso de sustantivo a adverbio conserva el significado raíz de disposición espontánea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116379, 'spa', 'El sentido activo central del Qal', 'El sentido activo central del Qal: huir, darse a la fuga ante un peligro o adversario, moviéndose rápidamente en una dirección definida lejos de la amenaza. Esto representa la mitad de las apariciones y abarca desde los habitantes de Madmena huyendo (Is 10:31) hasta reyes retirándose antes de la batalla (Sal 68:12). En español, huir selecciona vocabulario de escape deliberado, distinguiéndolo del vagar sin rumbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116381, 'spa', 'Vagar, deambular sin dirección fija ni hogar, a menudo como fugitivo o exiliado', 'Vagar, deambular sin dirección fija ni hogar, a menudo como fugitivo o exiliado. El participio Qal נוֹדֵד funciona casi como sustantivo (''errante, fugitivo''), como en Jer 49:5, donde los refugiados de Amón se dispersan sin nadie que los reúna. Proverbios 27:8 ofrece la memorable comparación del ave que vaga lejos de su nido. La distinción con el sentido 1 radica en la ausencia de dirección intencionada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116385, 'spa', 'El Hofal pasivo', 'El Hofal pasivo: ser expulsado, echado fuera, como receptor pasivo de la expulsión. Solo dos apariciones (2 S 23:6; Job 20:8), ambas vívidamente físicas: los malvados son ''ahuyentados'' como espinos, y el hombre próspero ''es echado'' como visión nocturna. El cambio de huida voluntaria a expulsión involuntaria queda claramente marcado por la voz pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116397, 'spa', 'Una única aparición que describe el aleteo o batir de alas (Is 10', 'Una única aparición que describe el aleteo o batir de alas (Is 10:14), donde Isaías se jacta de que ni un ala siquiera ''se movió'' cuando Asiria saqueó los nidos de las naciones. La imagen se nutre de la misma semántica de desplazamiento del nido que el sentido 2, pero se limita al movimiento físico del ave, un aleteo agitado y tembloroso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116398, 'spa', 'El Hitpael reflexivo', 'El Hitpael reflexivo: menear o sacudir la cabeza, un gesto de escarnio, burla o falsa compasión (Sal 64:8). Aunque solo hay una aparición, la raíz Hitpael marca un sentido verbal genuinamente distinto — movimiento corporal reflexivo en lugar de desplazamiento — y el registro social despectivo lo separa de todos los demás sentidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116400, 'spa', 'El Hifil causativo', 'El Hifil causativo: ahuyentar, expulsar a alguien activamente (Job 18:18). Aquí el sujeto ejecuta la expulsión: el malvado es ''ahuyentado de la luz a las tinieblas''. Este es la imagen especular del Hofal (sentido 3): lo que el sentido 3 experimenta pasivamente, el sentido 6 lo ejecuta activamente. Solo una aparición, pero la raíz causativa lo distingue inequívocamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116408, 'spa', 'Impureza menstrual específicamente', 'Impureza menstrual específicamente: el estado de inmundicia ritual asociado con el período de la mujer. Lev 12:2 compara la impureza posparto con ''los días de su נִדָּה'', y Lev 15:19-33 ofrece la legislación más completa. Ez 18:6 prohíbe acercarse a una mujer menstruante. El término regulaba aspectos prácticos de la vida comunitaria en el antiguo Israel y sigue siendo central en las discusiones de pureza ritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116409, 'spa', 'Impureza ritual o moral más amplia que trasciende la menstruación', 'Impureza ritual o moral más amplia que trasciende la menstruación. Las ''aguas de נִדָּה'' (Nm 19:9, 13, 20-21) purifican la contaminación por contacto con cadáveres — un contexto ritual completamente diferente. Lev 20:21 aplica נִדָּה a la abominación de casarse con la esposa del hermano. Proféticamente, Ez 36:17 compara la conducta de Israel con la inmundicia menstrual, y Zac 13:1 promete una fuente para la נִדָּה y el pecado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116423, 'spa', 'Expulsar, desterrar (Hifil)', 'Expulsar, desterrar (Hifil). Hifil: expulsar, desterrar o echar de la tierra o la comunidad. Usado prominentemente de Dios dispersando a Israel entre las naciones (Jer 8:3, 16:15) y de la expulsión religiosa forzosa (2 Cr 13:9). El Hifil marca al agente como causa del destierro, con fuerza activa e intencional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116424, 'spa', 'Ser desterrado (Nifal)', 'Ser desterrado (Nifal). Nifal pasivo: ser desterrado o convertido en proscrito, frecuentemente como participio sustantivado que significa ''el desterrado''. Central en las promesas de restauración: Dios reunirá ''a los desterrados de Israel'' (Is 56:8). El conmovedor diálogo de 2 Samuel 14:13-14 gira en torno a esta misma palabra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116427, 'spa', 'Desviar, seducir (Hifil)', 'Desviar, seducir (Hifil). Hifil con fuerza moral: desviar, seducir o apartar de la fidelidad. Concentrado en las advertencias de Deuteronomio contra los falsos profetas e instigadores a la idolatría (Dt 13:5, 10, 13), y en el juicio histórico sobre Jeroboam (2 Re 17:21). El árabe أَضَلَّ (extraviar) confirma la dimensión espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116434, 'spa', 'Empujar, derribar (Hifil)', 'Empujar, derribar (Hifil). Hifil con fuerza física: empujar violentamente o derribar, enfatizando el impacto corporal más que el exilio. Absalón advierte a David que Joab ''traerá'' calamidad sobre Jerusalén (2 Sam 15:14); el salmista describe enemigos que empujan para derribarlo (Sal 62:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116436, 'spa', 'Deslizarse, desprenderse', 'Deslizarse, desprenderse. Uso Nifal en Deuteronomio 19:5 que describe la cabeza del hacha que ''se desliza'' o ''se desprende'' del mango: un desplazamiento accidental y forzoso de un objeto. Aplicado a las leyes de las ciudades de refugio, designa un movimiento involuntario y mecánico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116440, 'spa', 'Ser perseguido (Hofal/Pual)', 'Ser perseguido (Hofal/Pual). Pasivos Hofal y Pual: ser expulsado o perseguido como pasivo intensivo, enfatizando la indefensión de la víctima. Isaías 8:22 describe a quienes son arrojados a la oscuridad, e Isaías 13:14 compara la caída de Babilonia con una gacela acosada: dispersa e indefensa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116453, 'spa', 'Blandir, impulsar herramienta', 'Blandir, impulsar herramienta. Infinitivo Qal en Deuteronomio 20:19 que describe el acto de blandir o lanzar un hacha contra los árboles durante un asedio. Es el significado físico básico de la raíz — impulsar una herramienta — del cual se desarrollaron los sentidos figurados de destierro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116455, 'spa', 'Ser arrastrado, tentado (Nifal)', 'Ser arrastrado, tentado (Nifal). Nifal con seducción interna: ser arrastrado o tentado en el corazón, particularmente hacia la idolatría. Ambas apariciones figuran en las solemnes advertencias de Deuteronomio: ser arrastrado a adorar sol, luna y estrellas (Dt 4:19) o apartarse de Jehová (Dt 30:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116456, 'spa', 'Animal extraviado', 'Animal extraviado. Participio Nifal en Deuteronomio 22:1 aplicado a un animal descarriado que ha sido ''expulsado'' o se ha extraviado, extendiendo el concepto de exilio de las personas al ganado. La ley exige devolver al animal, en paralelo con la preocupación ética por los ''desterrados'' hallada en otros pasajes con esta raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116466, 'spa', 'Persona noble, príncipe o dignatario — usado como sustantivo para alguien de alt', 'Persona noble, príncipe o dignatario — usado como sustantivo para alguien de alta posición social o autoridad política. El Cántico del Pozo celebra a los nobles (נְדִיבֵי) que cavaron con sus bastones (Nm 21:18), Ana canta que Dios sienta a los pobres entre príncipes (1 S 2:8), y Job y los Salmos emparejan frecuentemente נְדִיבִים con reyes y gobernantes (Job 12:21; Sal 47:10; 113:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116467, 'spa', 'Dispuesto, generoso o de corazón noble — describe la disposición interior de la ', 'Dispuesto, generoso o de corazón noble — describe la disposición interior de la persona más que su rango social. La convocatoria del tabernáculo reúne a todo נְדִיב לֵב, ''de corazón dispuesto'' (Éx 35:5, 22), David ora por un רוּחַ נְדִיבָה, ''espíritu dispuesto'' (Sal 51:12), y Ezequías se dirige a aquellos cuyos corazones están dispuestos para el servicio del templo (2 Cr 29:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116470, 'spa', 'Cosas nobles o cualidades nobles consideradas en abstracto — las virtudes, plane', 'Cosas nobles o cualidades nobles consideradas en abstracto — las virtudes, planes o acciones que caracterizan la verdadera nobleza. Isaías 32:5 advierte que al necio ya no se le llamará נָדִיב, e Is 32:8 declara que el noble planea נְדִיבוֹת (''cosas nobles'') y por cosas nobles se mantiene firme. Cantares 6:12 aporta el enigmático עַמִּי נָדִיב, que puede significar ''mi pueblo noble'' en sentido abstracto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116488, 'spa', 'Ser aventado, arrastrado (Nifal)', 'Nifal pasivo: ser aventado, arrastrado o dispersado sin remedio, describiendo tamo, rastrojo u hojas llevados por el viento. Levítico 26:36 advierte que los desobedientes huirán al «sonido de una hoja arrastrada», e Isaías 19:7 lo aplica a la vegetación junto al Nilo. El Salmo 68:2 emplea el símil «como el humo es disipado». Las glosas ''aventada'' y ''arrastrada'' reflejan bien la calidad pasiva e indefensa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116489, 'spa', 'Aventar, dispersar (Qal)', 'Qal activo: aventar o dispersar algo con fuerza, con Dios o el viento como agente que esparce a los enemigos o el tamo. El Salmo 1:4 ofrece la imagen paradigmática: el viento «arrebata» a los impíos como tamo de la era. En Job 32:13, Elihú advierte a Israel que no digan «Dios lo derribará». Las glosas ''aventarás'' y ''lo dispersa'' subrayan la acción enérgica y deliberada del agente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116496, 'spa', 'Hacer un voto solemne o promesa a Dios, tipicamente involucrando un compromiso c', 'Hacer un voto solemne o promesa a Dios, tipicamente involucrando un compromiso condicional de ofrendas, dedicacion o servicio. El patron clasico es nadar neder, ''hacer un voto,'' visto en el voto de Jacob en Betel (Gn 28:20), la oracion de Ana (1 S 1:11) y la consagracion del nazareo (Nm 6:2). Deuteronomio y Eclesiastes subrayan la gravedad del cumplimiento: un voto una vez pronunciado se convierte en una obligacion vinculante ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116519, 'spa', 'Voto o promesa solemne hecha a Dios, que abarca tanto el acto de prometer como l', 'Voto o promesa solemne hecha a Dios, que abarca tanto el acto de prometer como lo prometido — ya sea un sacrificio (Lv 7:16; 22:21), una consagración personal como nazareo (Nm 6:2, 5, 21), o un compromiso condicional buscando el favor divino (Gn 28:20; 1 S 1:11; 2 S 15:7-8). Números 30 proporciona legislación detallada sobre la fuerza vinculante y la anulación de los votos. Todos los idiomas de destino emplean un único término equivalente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116544, 'spa', 'Guiar o conducir personas en un viaje o por un camino', 'Guiar o conducir personas en un viaje o por un camino. El Salmo 80:1 invoca a Dios como quien ''guía a José como un rebaño'', y Eclesiastés 2:3 lo usa para dirigir el propio corazón. En español, guiar y conducir reflejan el sentido activo y deliberado de un líder que lleva a otros por una ruta, ya sea física o figurada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116546, 'spa', 'Llevar por la fuerza o arrebatar como botín', 'Llevar por la fuerza o arrebatar como botín. Génesis 31:26 tiene a Labán acusando a Jacob de ''llevarte a mis hijas como cautivas'', y 1 Samuel 30:2 describe a los amalecitas llevándose cautivos. Lamentaciones 3:2 extiende esto a Dios conduciendo al hablante a las tinieblas. El desplazamiento hacia la compulsión marca este sentido como el extremo hostil del rango semántico del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116548, 'spa', 'La raíz intensiva Piel transmite una guía deliberada y sostenida por parte de un', 'La raíz intensiva Piel transmite una guía deliberada y sostenida por parte de una figura de autoridad. Dios guía el viento del este por el cielo (Sal 78:26) y conduce a su pueblo por el desierto (Éx 14:25, donde ''trabó'' las ruedas de los carros egipcios). La cualidad cuidadosa y autoritaria distingue esta raíz intensificada de la conducción ordinaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116551, 'spa', 'El sentido pastoral concreto de arrear o conducir ganado — rebaños, manadas o as', 'El sentido pastoral concreto de arrear o conducir ganado — rebaños, manadas o asnos — empujándolos hacia adelante. Génesis 31:18 describe a Jacob conduciendo todo su ganado, y 1 Samuel 23:5 relata a David llevándose el ganado de los filisteos. En español, conducir y arrear captan la naturaleza enérgica y directa de mover animales en masa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116574, 'spa', 'Lamentarse con duelo', 'Gemir o lamentarse con aflicción audible. En 1 Samuel 7:2, «toda la casa de Israel se lamentaba en pos del SEÑOR», un anhelo vocal durante la ausencia del arca. Ezequiel 32:18 lo emplea como duelo profético ordenado por Dios contra Egipto. Miqueas 2:4 lo proyecta al futuro: un lamento amargo como parte del juicio divino. El verbo denota una expresión sonora e intensa de dolor o súplica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116575, 'spa', 'Lamento, endecha', 'Lamento formalizado o endecha, entonado típicamente en respuesta a juicio profético o pérdida catastrófica. En Jeremías 9:10 se ''levanta'' (נָשָׂא) sobre las montañas, emparejado con lloro (בְּכִי) y la elegía fúnebre (קִינָה). Amós 5:16 menciona plañideros profesionales ''diestros en el נְהִי'', indicando que no se trataba de simple dolor espontáneo sino de un arte vocal estructurado. Miqueas 2:4 lo emplea como término genérico para la canción de lamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116583, 'spa', 'Guiar, conducir', 'Piel: guiar, conducir o llevar a alguien hacia un destino, especialmente un lugar de agua o descanso. La raíz se conecta con el árabe manhal (''abrevadero''), iluminando su trasfondo pastoril. Dios guía a su pueblo con misericordia hacia su santa morada (Éx 15:13), conduce junto a aguas de reposo (Sal 23:2) y los guiará a manantiales de agua (Is 49:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116591, 'spa', 'Avanzar suavemente', 'Hitpael: proceder con suavidad, conducir a paso lento y acomodado. En Génesis 33:14, Jacob dice a Esaú que ''conducirá lentamente'' (etenaahalah) al ritmo de los niños y el ganado. El Hitpael reflexivo-iterativo transmite un movimiento mesurado y cuidadoso, no una marcha vigorosa, distinguiéndose del Piel por su cadencia pausada y deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116593, 'spa', 'Ciudad de Zabulón', 'Nahalal (o Nahalol), ciudad en el territorio de Zabulón. Josué 19:15 la enumera entre las ciudades de la herencia zabulonita, incluyendo «Catat, Nahalal, Simrón, Idala y Belén». Josué 21:35 la asigna a los levitas con sus ejidos. Jueces 1:30 registra la conquista incompleta: Zabulón no expulsó a sus habitantes, quienes fueron sometidos a trabajo forzado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116595, 'spa', 'Gruñido y gemido', 'El gruñido profundo y sostenido de un león mientras devora su presa, distinto del rugido de ataque. Se usa figuradamente de Asiria como león devorador en Isaías 5:29-30 y de un gobernante malvado en Proverbios 28:15. En el ámbito humano, expresa el gemido de angustia o sufrimiento, como en Proverbios 5:11 y Ezequiel 24:23.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116599, 'spa', 'Afluir hacia', 'Fluir o afluir hacia un destino, usado exclusivamente en contextos figurados de personas moviéndose en abundancia. Isaías 2:2 y su paralelo Miqueas 4:1 profetizan que «todas las naciones afluirán hacia él» (וְנָהֲרוּ אֵלָיו), confluyendo al monte exaltado del templo de YHWH en Jerusalén para aprender sus caminos. Jeremías 31:12 invierte la dirección: el Israel restaurado «afluirá hacia» (וְנָהֲרוּ אֶל) la bondad del Señor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116601, 'spa', 'el Río (Éufrates)', 'Sustantivo arameo para ''río'', empleado predominantemente como designación geográfico-política del Éufrates en la frase ''al otro lado del Río'' (עֲבַר נַהֲרָה), refiriéndose a la satrapía del Trans-Éufrates del Imperio Persa. Este uso formulario domina la correspondencia imperial de Esdras (Esd 4:10, 11, 16, 17, 20; 5:3, 6; 6:6, 8, 13; 7:21, 25; 8:36). En Daniel 7:10, el mismo sustantivo adquiere fuerza apocalíptica como ''río de fuego''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116603, 'spa', 'río, corriente perenne', 'Un río perenne o corriente principal, empleado para cursos de agua específicos como el Éufrates (''el Río'', Gn 15:18; Dt 1:7), los ríos del Edén (Gn 2:10-14) y las corrientes de la región del Nilo (Is 19:6). En textos poéticos y proféticos, nahar adquiere dimensiones cosmológicas y escatológicas — torrentes primordiales que desafían la soberanía de Dios (Sal 93:3), ríos que se regocijan ante su venida (Sal 98:8) y aguas sanadores que brotan del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116642, 'spa', 'Impedir, prohibir, restringir', 'Impedir, prohibir o restringir, especialmente en el contexto legal de anular votos. Números 30:5-11 establece que un padre o esposo que ''prohíbe'' el día que escucha el voto de una mujer lo invalida ante Dios. El Salmo 33:10 amplía el sentido a la frustración divina de los planes de las naciones. Tanto ''prohibir'' como ''deshacer'' captan este acto de autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116643, 'spa', 'Desalentar, desanimar', 'Desalentar o desanimar, quebrando la resolución y la voluntad de actuar de un grupo. Números 32:7-9 emplea este sentido específicamente respecto a los líderes tribales que ''desalentaron el corazón de los hijos de Israel'' para que no cruzaran a Canaán, evocando la catastrófica incredulidad provocada por el informe de los espías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116649, 'spa', 'Dar fruto', 'Dar fruto, producir o florecer, usado exclusivamente en contextos figurados. Proverbios 10:31 declara que «la boca del justo produce (יָנוּב) sabiduría», representando el habla sabia como fruto natural de una vida recta. Salmo 92:14 promete que los justos «aún darán fruto (יְנוּבוּן) en la vejez», manteniéndose productivos pese a los años. Salmo 62:10 advierte que «si la riqueza da fruto», no se debe poner el corazón en ella.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116653, 'spa', 'Qal de desplazamiento físico', 'Qal de desplazamiento físico: vagar, huir, ser fugitivo, moviéndose sin dirección fija ni hogar. Este es el sentido de la maldición de Caín — ''errante y vagabundo serás en la tierra'' (Gn 4:12, 14). El participio נָד se convierte prácticamente en un título para el desplazado. En español, andar errante capta la cualidad sin rumbo y forzada de este movimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116654, 'spa', 'Qal de respuesta emocional', 'Qal de respuesta emocional: lamentarse, condolerse, mostrar compasión por el sufrimiento ajeno. Los tres amigos de Job vinieron ''a condolerse de él y consolarlo'' (Job 2:11); tras su restauración, los parientes ''se condolieron de él'' (Job 42:11). El salmista esperó a alguien que ''se compadeciera'', pero no encontró a nadie (Sal 69:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116657, 'spa', 'Hifil causativo', 'Hifil causativo: hacer vagar, sacudir o ahuyentar — la contraparte activa y transitiva de los sentidos 1 y 4. Dios sacudirá a Israel como una caña (1 Re 14:15 pertenece conceptualmente al marco Hifil); el salmista ruega que la ''mano del impío'' no lo ''ahuyente'' (Sal 36:11); y las cabezas se menean ante ciudades arruinadas (Jer 18:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116658, 'spa', 'Qal/Hitpael de oscilación física', 'Qal/Hitpael de oscilación física: mecerse, tambalearse, oscilar, describiendo el movimiento inestable de objetos o cuerpos. Israel será sacudido ''como se sacude una caña en el agua'' (1 Re 14:15), y la tierra ''se tambalea como un borracho'' (Is 24:20). En español, bambolearse capta la cualidad oscilante y pendular. Este es posiblemente el sentido más básico del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116659, 'spa', 'Hitpael reflexivo/intensivo', 'Hitpael reflexivo/intensivo: gemir o lamentarse de sí mismo en lamento personal, expresando un dolor intenso dirigido hacia adentro. Una única aparición en Jer 31:18, donde se escucha a Efraín ''lamentándose'' con pesar autodirigido. La morfología reflexiva del Hitpael confirma la cualidad introspectiva: no compasión por otro (sentido 2) sino el propio mecer y gemir del sujeto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116665, 'spa', 'Hitpael como gesto de desprecio', 'Hitpael como gesto de desprecio: sacudir o menear la cabeza hacia alguien en burla, lástima o asombro. En Jer 48:27, la burla contra Moab pregunta si Israel fue ''objeto de escarnio'' — es decir, burlado con un meneo de cabeza. En español, menear la cabeza identifica el gesto con precisión. Aunque solo hay una aparición, la evidencia interlingüística lo confirma consistentemente como un sentido distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116681, 'spa', 'Un lugar de residencia establecido o habitacion para personas o para Dios, enfat', 'Un lugar de residencia establecido o habitacion para personas o para Dios, enfatizando un hogar u morada asentada y a menudo hermosa. Este sentido dominante (22 apariciones) abarca desde la santa morada de Dios en el Cantico del Mar (Ex 15:13) hasta la esperanza de Job de que Dios restaure la morada de su justicia (Job 8:6). Tambien incluye la vision profetica de Jerusalen o Sion como morada de Dios (Jer 25:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116683, 'spa', 'Pastizal abierto o pradera verde donde los rebanos pacen libremente, destacando ', 'Pastizal abierto o pradera verde donde los rebanos pacen libremente, destacando el paisaje pastoral de alimentacion mas que de cercamiento. Siete apariciones se centran en la imagen del pastor y el rebano: Dios tomo a David del naveh -- los pastizales de ovejas -- para pastorear a Israel (2 S 7:8; 1 Cr 17:7), y Saron se convertira en pastizal para los rebanos (Is 65:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116691, 'spa', 'Un redil o lugar de descanso protegido donde los rebanos reposan en seguridad, d', 'Un redil o lugar de descanso protegido donde los rebanos reposan en seguridad, distinguido del pastizal abierto por la connotacion de recinto delimitado y reposo seguro. Cinco apariciones se agrupan en contextos profeticos: Dios traera de vuelta a las ovejas dispersas a su redil (Jer 23:3), la tierra de Amon se convertira en lugar de descanso para camellos (Ez 25:5), y el pueblo restaurado hallara buen pasto y descansara en seguridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116709, 'spa', 'Hifil causativo', 'Hifil causativo: dar descanso o conceder alivio, especialmente cuando Dios otorga a su pueblo respiro de enemigos, guerras u opresión. Este es el descanso pactual que estructura la teología deuteronómica de la tierra (Dt 3:20; 12:10; 25:19) y resuena a lo largo de Josué y Crónicas. El árabe araaha (forma IV causativa de r-w-h) refleja exactamente la morfología causativa del hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116710, 'spa', 'Qal intransitivo', 'Qal intransitivo: descansar del trabajo, cesar de la labor, hallar reposo. Es el sentido por excelencia del descanso sabático de la creación: Dios descansó el séptimo día (Éx 20:11), y el mandamiento se extiende a siervos, animales y extranjeros (Éx 23:12; Dt 5:14). El árabe istaraha (forma X reflexiva) distingue este reposo autodirigido del otorgamiento causativo del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116711, 'spa', 'Hifil con sentido de colocación física', 'Hifil con sentido de colocación física: depositar, poner o colocar algo en un lugar específico. Distinto del sentido abstracto de ''conceder descanso'' del sentido 1, este es un posicionamiento concreto: Ezequiel es puesto en un valle de huesos secos (Ez 37:1), luego sobre un monte alto (Ez 40:2); Moisés baja las manos y Amalec prevalece (Éx 17:11). El árabe anzala (forma IV de n-z-l, ''bajar, depositar'') refleja este matiz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116724, 'spa', 'Qal', 'Qal: posarse, asentarse, reposar en un lugar — referido a objetos, animales o el Espíritu más que al descanso personal. El arca se asienta sobre Ararat (Gn 8:4), las langostas se posan sobre la tierra (Éx 10:14), y de manera notable, el Espíritu del SEÑOR reposa sobre los setenta ancianos (Nm 11:25-26) y sobre el Renuevo venidero (Is 11:2). El árabe istaqarra (''estacionarse, asentarse'') capta esta idea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116736, 'spa', 'Una única ocurrencia difícil en Lm 5', 'Una única ocurrencia difícil en Lm 5:5 donde el sentido puede ser ''no hay descanso para nosotros'' en el contexto de agotamiento bajo persecución. El versículo describe la persecución con yugos sobre los cuellos y sin respiro. Probablemente refleja un raro Hofal pasivo o una construcción sintáctica inusual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116751, 'spa', 'Una anomalía de análisis morfológico en 2 S 17', 'Una anomalía de análisis morfológico en 2 S 17:12 donde la forma consonántica nachnu se leyó como ''nosotros'' (el pronombre de primera persona plural) en lugar de una forma verbal de nuach. La evidencia multilingüe es unánime: español ''y nosotros'', confirmando que se trata de un pronombre homógrafo, no de un sentido semántico del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116768, 'spa', '(en Naioth)', 'Nombre de lugar que designa la morada de la comunidad profética en o cerca de Ramá, donde Samuel presidía. Aparece exclusivamente en el relato de la huida de David de Saúl (1 Sam 19:18-23; 20:1). Se destaca por el derramamiento repetido del Espíritu que hizo profetizar involuntariamente a los mensajeros de Saúl y al propio Saúl. El nombre probablemente deriva de naveh (''morada'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116774, 'spa', 'Muladar o estercolero', 'Un muladar o montón de inmundicia. Esdras 6:11 registra el decreto de Darío: «quien altere este edicto, sea arrancada una viga de su casa, sea empalado en ella, y su casa sea convertida en muladar». Daniel 2:5 recoge la amenaza de Nabucodonosor: quienes no revelen el sueño serán despedazados y sus casas hechas muladar. Daniel 3:29 repite la fórmula como castigo por blasfemia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116775, 'spa', 'Dormitar, adormecerse', 'Estar somnoliento o dormitar, denotando sueño ligero y frecuentemente desatención culpable. El punto teológico cumbre es el Salmo 121:3-4, donde la negativa de Dios a dormitar garantiza la seguridad de Israel. Los profetas condenan a líderes que se amodorran: los pastores de Nínive dormitan (Nah 3:18) y los centinelas aman el sopor (Isa 56:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116782, 'spa', 'El nombre propio del padre de Josué, de la tribu de Efraín', 'El nombre propio del padre de Josué, de la tribu de Efraín. Aparece invariablemente en la fórmula patronímica fija ''Josué hijo de Nun'' a lo largo del Pentateuco (Éx 33:11; Nm 11:28; Dt 1:38), las narrativas de la conquista (Jos 1:1; 2:1) y referencias posteriores (Jue 2:8; 1 Re 16:34; Neh 8:17). La genealogía de 1 Crónicas 7:25-27 sitúa a Nun en la línea efraimita. No se preserva ninguna narrativa independiente sobre él; su función es exclusivamente patronímica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116783, 'spa', 'huir, escapar (Qal)', 'Significado nuclear del Qal que abarca la gran mayoría de las ocurrencias: huir o escapar del peligro, de los enemigos, de la batalla o del juicio divino. Desde Jacob huyendo de Esaú hasta ejércitos israelitas puestos en fuga, este sentido permea la narrativa, la ley (ciudades de refugio, Nm 35:25) y la poesía por igual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116794, 'spa', 'fugitivo (participio Qal)', 'El participio Qal empleado como sustantivo: un fugitivo o refugiado, alguien caracterizado por el estado de huida. Éx 14:27 describe a los egipcios ''huyendo hacia'' el mar, mientras que Jer 48:19 pregunta a los fugitivos de Moab qué ha ocurrido. El participio sustantivado captura la condición permanente o definitoria de quien huye.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116807, 'spa', 'poner en fuga (Hifil)', 'El Hifil causativo: hacer huir a alguien, poner en fuga o ahuyentar. Dt 32:30 pregunta cómo uno podría perseguir a mil, y Jue 7:21 describe la derrota provocada por Gedeón. Es la única conjugación en la que el sujeto causa la huida en vez de experimentarla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116810, 'spa', 'esconder, ocultar', 'Ocurrencia única en Jue 6:11, donde el contexto sugiere esconder u ocultar (trillar trigo en un lagar para ocultarlo de los madianitas). Se trata de una extensión contextual de la huida al ocultamiento que esta persigue como fin.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116811, 'spa', 'impulsar, arrastrar', 'En Is 59:19, el verbo aparece en un pasaje disputado donde el Espíritu del SEÑOR ''impulsa'' o ''pone en fuga'' al enemigo como un torrente impetuoso. El matiz es de movimiento enérgico y arrollador, aunque el análisis morfológico exacto sigue siendo debatido entre los comentaristas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116812, 'spa', 'desvanecerse, perderse', 'En Dt 34:7, aplicado a Moisés al morir: su vigor ''no se había desvanecido''. El sentido concreto de huida física se extiende metafóricamente a la partida de la vitalidad o la fuerza — una elegante personificación del envejecimiento donde el vigor ''huye'' del cuerpo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116832, 'spa', 'alzarse, ondear', 'En Sal 60:4 (60:6 TM), un texto difícil donde nus parece significar ''alzarse'' o ''ser levantado'' en relación con una bandera. El movimiento es ascendente en lugar de centrífugo — posiblemente una raíz homógrafa o una extensión semántica notable de la huida al acto de enarbolar un estandarte de reunión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116846, 'spa', 'Oscilar, tambalear o bambolearse -- movimiento inestable de vaiven, el sentido f', 'Oscilar, tambalear o bambolearse -- movimiento inestable de vaiven, el sentido fisico central con 13 apariciones. Los arboles de la fabula de Jotam se niegan a ''mecerse'' sobre la zarza (Jue 9:9, 11, 13); los labios de Ana se mueven mientras ora y Eli la cree ebria (1 S 1:13); la tierra ''se tambalea como un borracho'' bajo el juicio divino (Is 24:20); Job 28:4 describe a mineros que cuelgan y se balancean.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116847, 'spa', 'Hifil transitivo', 'Hifil transitivo: sacudir o menear algo deliberadamente -- 9 apariciones donde el sujeto es un agente activo que causa el movimiento. Menear la cabeza en burla o escarnio es la imagen dominante: los transeuntes ''menean la cabeza'' ante el salmista sufriente (Sal 22:7; 109:25), la hija de Sion ''menea la cabeza'' ante los asirios en retirada (2 R 19:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116848, 'spa', 'Vagar o deambular como fugitivo o persona sin hogar -- 10 apariciones que captan', 'Vagar o deambular como fugitivo o persona sin hogar -- 10 apariciones que captan un movimiento errante y sin rumbo. El caso primordial es la maldicion de Dios sobre Cain: na vanad, ''errante y vagabundo'' (Gn 4:12, 14), donde la duplicacion con nad intensifica el desarraigo. El Salmo 109:10 pide que los hijos del malvado ''vaguen y mendiguen''; el Salmo 59:15 describe a los enemigos ''vagando en busca de comida.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116852, 'spa', 'Hifil causativo', 'Hifil causativo: hacer vagar a alguien o dispersarlo -- 4 apariciones donde Dios o una autoridad empuja a las personas al desplazamiento. Dios hizo ''vagar'' a Israel cuarenta anos por el desierto (Nm 32:13); David le dice a Itai ''te hare vagar con nosotros?'' (2 S 15:20); el salmista ora ''hazlos vagar'' (Sal 59:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116863, 'spa', 'Temblar, estremecerse o sacudirse de miedo o asombro -- 4 apariciones donde el m', 'Temblar, estremecerse o sacudirse de miedo o asombro -- 4 apariciones donde el movimiento es involuntario y emocional mas que locomotor. En el Sinai el pueblo ''temblo'' y se mantuvo a distancia (Ex 20:18); los arboles del bosque -- representando a la casa de David -- ''se estremecieron como se estremecen los arboles ante el viento'' ante la alianza siro-efraimita (Is 7:2); los idolos de Egipto ''tiemblan'' ante el Senor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116868, 'spa', 'Zarandear o sacudir como en un cedazo -- 2 apariciones, ambas en Amos 9', 'Zarandear o sacudir como en un cedazo -- 2 apariciones, ambas en Amos 9:9, donde Dios declara ''zarandeare la casa de Israel entre todas las naciones, como se zarandea el grano en un cedazo.'' El Hifil causativo aqui se extiende mas alla del vagar humano hacia una metafora agricola: Dios cierne a Israel como un agricultor cierne el trigo, y ''ni un guijarro caera a tierra.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116884, 'spa', 'El uso mas frecuente', 'El uso mas frecuente: mecer una porcion de sacrificio u ofrenda de un lado a otro ante el Senor en el ritual de la tenufah (ofrenda mecida). Casi todas las apariciones se agrupan en Exodo y Levitico. El espanol ''mecer'' capta el movimiento suave de balanceo, mientras que el aleman ''Webe'' (de ''weben,'' tejer) evoca el patron de vaiven. El pecho y el muslo derecho de la ofrenda de paz eran las piezas habituales mecidas (Lv 7:30; 9:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116891, 'spa', 'Empunar, blandir o esgrimir una herramienta o arma con fuerza e intencion', 'Empunar, blandir o esgrimir una herramienta o arma con fuerza e intencion. En Ex 20:25 y Dt 27:5, no se deben empunar herramientas de hierro contra las piedras del altar. Isaias 10:15 plantea la famosa pregunta retorica: puede el hacha jactarse sobre quien la empuna? El espanol emplea aqui ''alzar'' o ''blandir,'' reflejando el movimiento ascendente en vez del gesto ritual lateral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116894, 'spa', 'Agitar o sacudir la mano en un gesto amenazante o de autoridad, claramente no ri', 'Agitar o sacudir la mano en un gesto amenazante o de autoridad, claramente no ritual. Dios agita su mano sobre la hija de Sion (Is 10:32) y sobre Egipto (Is 19:16). Zacarias 2:9 promete que Dios agitara su mano sobre las naciones opresoras. El gesto comunica autoridad divina y juicio inminente -- mas que simple movimiento, es una senal soberana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116906, 'spa', 'Un unico uso metaforico en Is 30', 'Un unico uso metaforico en Is 30:28 donde el Senor criba a las naciones con el ''cedazo de destruccion.'' El movimiento de vaiven de la raiz se traslada naturalmente al aventamiento o cribado del grano, y el espanol ''cribar'' capta con precision esta transferencia agricola. Extiende la oscilacion fisica a una imagen de separacion y dispersion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116911, 'spa', 'Plumaje de aves', 'Plumaje o plumas, la cobertura emplumada completa de las aves. Ezequiel 17:3 describe una gran águila «de grandes alas, largos plumones y plumaje abundante» (מָלֵא הַנּוֹצָה) que representa a Nabucodonosor, cuyo copioso plumaje simboliza magnificencia real. Ezequiel 17:7 retrata otra águila «de grandes alas y mucho plumaje» (רַב נוֹצָה) que representa al faraón de Egipto. Job 39:13 contrasta el plumaje del avestruz con el de la cigüeña.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116913, 'spa', 'Fuego como elemento físico, usado exclusivamente en Daniel tanto para instrument', 'Fuego como elemento físico, usado exclusivamente en Daniel tanto para instrumentos humanos de persecución como para imágenes teofánicas divinas. En la narrativa del horno de fuego, נוּר aparece repetidamente como medio del castigo amenazado por Nabucodonosor contra quienes rechazan la idolatría (Dan 3:6, 11, 15, 17, 20-27), del cual los tres fieles son milagrosamente librados ilesos. En la visión nocturna de Daniel, el fuego se convierte en el elemento propio de la majestad divina: el trono del Anciano de Días arde en llamas, sus ruedas son fuego ardiente, y un río de fuego fluye ante él (Dan 7:9-10).');